		if err != nil {
			return "", fmt.Errorf("resolve output directory: %w", err)
		}
		info, statErr := os.Stat(abs)
		if statErr == nil && !info.IsDir() {
			return "", fmt.Errorf("output path exists and is not a directory: %s", abs)
		}
		if statErr != nil && !os.IsNotExist(statErr) {
