func newPathCommand(opts Options) *cobra.Command {
	pathOpts := pathCommandOptions{
		checkpointLimit: defaultCheckpointLimit,
		entireBinary:    "entire",
		scope:           exportScopeAll,
	}

	cmd := &cobra.Command{
