	applySessionSourceAliases(manifest)
	return writeBrainManifestAndReadme(outputDir, *manifest)
}

func applySessionSourceAliases(manifest *exportManifest) {
	if manifest.Sources == nil || manifest.Sources.Sessions == nil {
